'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var dlarfb = require( './../lib' );

// Specify matrix meta data:
var shape = [ 3, 3 ];
var strides = [ 1, 3 ];
var offset = 0;
var order = 'row-major';

// Create input matrices stored in linear memory:
var V = new Float64Array( [ 10.0, 40.0, 70.0, 20.0, 50.0, 80.0, 30.0, 60.0, 90.0 ] ); // eslint-disable-line max-len
var T = new Float64Array( [ 1.0, 0.0, 0.0, 0.0, 2.0, 0.0, 0.0, 0.0, 3.0 ] );
var C = new Float64Array( [ 11.0, 12.0, 13.0, 21.0, 22.0, 23.0, 31.0, 32.0, 33.0 ] ); // eslint-disable-line max-len
var work = new Float64Array( 9 );

console.log( 'Input matrix C:' );
console.log( ndarray2array( C, shape, strides, offset, order ) );

dlarfb( order, 'left', 'transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 );

console.log( 'Output matrix C after applying block reflector:' );
console.log( ndarray2array( C, shape, strides, offset, order ) );
